-- Week 1's chapters for the online game, generated by scripts/gen-chapters-sql.ts from src/data/chapterScripts.ts
-- (itself generated from docs/canon/episode-1-*.md). Do not edit by hand.
insert into public.chapters (series_id, season_number, week, day, script, meta) values
('dark-moon', 1, 1, 1, $json${"week":1,"day":1,"title":"The forest road","heading":"The old forest road","question":"who is this man, and what does he want with me?","steps":[{"t":"say","text":"The old forest road has not been mended in a generation. Roots have shouldered up through it and the ruts are full of last year's leaves. Overhead the trees lean so close that the afternoon comes down through them green and thin, like light through bottle glass. It smells of wet bark. Nothing sings.\n\nYour wagon has been complaining about the road for miles. Then the axle gives with a crack that goes off through the trees, and the whole cart lurches down onto one corner and is still.\n\nIn the quiet afterwards, something moves in the treeline.\n\nA man steps out onto the road with his blade already drawn. He does not ask for your purse. He does not say anything at all.\n\n…"},{"t":"fight","name":"A MAN ON THE ROAD","desc":"He means it. So must you.","firstLines":null,"strikeFirst":{"on":"player"}},{"t":"say","text":"Steel rings on steel, and the wood swallows the sound. Then, between one blow and the next, he breaks off. One look at you, level and unhurried, and he is gone into the trees before you can lay a hand on him. For a few strides you can hear him in the bracken. Then you cannot.","cond":{"on":"fight","won":true}},{"t":"say","text":"You are on your back in the road, with leaf-mould in your mouth and the green roof turning slowly overhead. He could finish it. He looks down at you for a long moment, and then he is gone into the trees.","cond":{"on":"fight","won":false}},{"t":"say","text":"The road is very quiet. Somewhere off among the trunks, a single bird starts up again."},{"t":"choice","id":0,"labels":["LOOK WHERE HE STOOD","LOOK AT WHAT HE WAS AT"],"mode":"each","branches":[{"options":[0],"text":"A scrap of parchment in the leaf-mould, half burned. Its scorched edge flakes at your touch and still smells faintly of smoke. It is not writing and it is not a drawing. Somebody laid it over something hard and raised, and rubbed charcoal across it until the shape came through.\n\nYou turn it to the light and back again. You do not know the shape.\n\n…"},{"options":[1],"text":"Your cargo box, slewed half off the tilted wagon bed. The lock is jammed. The scratches round it are fresh, bright in the dull old metal. They are not yours.\n\nHe was at this before you ever saw him.\n\n…"}]},{"t":"notice","lines":{"Might":{"first":"He held back. Every blow came a half-beat late."},"Craft":{"first":"The lock was not forced open. It was forced shut."},"Intellect":{"first":"A robber goes for the purse and the horse. He went for neither."},"Charm":{"first":"He never once looked angry. He looked like a man doing a job."},"Agility":{"first":"He was in the trees before your axle went. He was waiting for it."},"Aim":{"first":"That axle did not snap. It was cut most of the way through."}}},{"t":"say","text":"…"},{"t":"challenge","title":"OPEN THE BOX","desc":"You need to know what he wanted in here, and the light is going on a road he knows better than you do.","options":[{"attr":"Might","verb":"force it"},{"attr":"Craft","verb":"work the jammed mechanism free"}],"reward":"+500g","fail":"it costs you skin and most of an hour of daylight"},{"t":"say","text":"The lock fights you for a moment. Then something inside it gives with a small, dull click. The lid comes up in your hands while there is still light enough to see by.","cond":{"on":"challenge","pass":true}},{"t":"say","text":"It does not want to give, and it takes its time about it. It takes some of your skin as well. When the lid comes up at last your knuckles are bleeding and the trees have gone from green to black.","cond":{"on":"challenge","pass":false}},{"t":"say","text":"You go through the box twice, by what light is left. Everything you own is here, folded the way you folded it. Nothing has been taken.\n\nSomething has been put in.\n\nA second scrap, clean and unburned: a list, in a neat, steady hand. **{N} names. Yours is one of them.** Under them a single line that is not a name.\n\n**The Hollow Wake Inn, on the drove road.**"},{"t":"say","text":"You leave the wagon where it lies and walk the last of the dusk down to the crossroads. Where your road meets the drove road an old boundary stone stands half-buried in the verge, weathered past reading. Moss furs its north side. Something in a crack at its foot catches the last of the light."},{"t":"act","label":"PULL IT OUT"},{"t":"say","text":"Thin, dense, and cold in a way nothing should be at this time of year. It lies across your palm like a sliver of winter that has forgotten to melt. It is not paper. It has not aged the way paper would.\n\n**A locked Seeker Fragment has been added to your Chest.**","fragment":true},{"t":"say","text":"You sit a while on the stone with the list in one hand and the cold thing in the other. The dark comes down through the trees, and somewhere an owl tries its voice.\n\nA man broke into your box to leave you a list with your name on it.\n\n**One day north: the Hollow Wake Inn. Somebody wants you there.**","pull":true},{"t":"summary","lines":["**THE FOREST ROAD** · Day 1","You earned: `[gold]` · your class Attribute `[growth]`","You learned: nothing was taken. A list of {N} names was left for you, and the name of an inn.","You hold: the list · a half-burned charcoal rubbing","Fragment: 1 found, locked","Tomorrow: **the Hollow Wake Inn, a day north**"]}]}$json$::jsonb, $json${"dc":6,"wDef":22,"wAtk":15,"fightReward":300}$json$::jsonb),
('dark-moon', 1, 1, 2, $json${"week":1,"day":2,"title":"The Hollow Wake Inn","heading":"The Hollow Wake Inn","question":"who are the others on the list, and who wrote it?","steps":[{"t":"say","text":"A day on the drove road, between hedges nobody has cut in years. At the end of it, low under its own dark thatch, stands the Hollow Wake Inn. One window is lit. The sign over the door has been painted so many times that whatever it showed has gone soft at the edges, like a face on an old coin.\n\nThe taproom is warm and low and smells of woodsmoke. Underneath the smoke is the smell of ale soaked a long time into old boards. There are {N-1} strangers in it who are not drinking.\n\n{F1} has a torn page flat on the table under one hand. {F2} is turning one over and over. {F3}'s is folded small, the way you fold a thing you have read too many times.\n\nYou put yours down beside them. The same neat hand. The same names, each with a date beside it.\n\n{F1} moves along the bench to make room. The fire settles in the grate. Nobody has to explain."},{"t":"say","text":"The innkeeper sets down the cups. He sets down one more than there are of you, at the empty end of the table, and goes back behind his bar. He has a cloth over one shoulder. He moves the way a man moves in a room he has crossed ten thousand times, with no hurry in him at all."},{"t":"act","label":"ASK HIM ABOUT THE LIST"},{"t":"say","text":"You begin to ask. Before you are halfway through he gives you his name, plainly, the way he might give you the price of a room.\n\n*\"Garrick.\"*\n\nHe comes round the end of the bar and looks at the pages for a while, not touching them. Then he goes back, reaches under the counter, and brings out a satchel, worn soft at the corners.\n\n*\"Woman called Meira. Scholar. Sat right there most nights, two years near enough. Cheapest wine in the house, and tipped like a queen.\"*\n\nHe puts it on the table.\n\n*\"Left this. Hasn't been back in three weeks.\"*"},{"t":"say","text":"Inside is a notebook, packed to the margins in the hand you all know by now. It smells of dust and lamp smoke. The pages have gone soft with handling. Your names are in it. Every one of you.\n\n{STAKE}\n\nAnd near the back, where the binding shows, some pages are gone.\n\n…"},{"t":"notice","lines":{"Might":{"first":"The satchel strap has been mended three times.","second":"She carried this a long way, often."},"Agility":{"first":"{F2}'s knuckles are skinned. So are {F3}'s.","second":"Every one of you fought somebody to get here."},"Intellect":{"first":"The notes are in two inks.","second":"She came back to these pages years apart."},"Charm":{"first":"The innkeeper has not asked a single one of you your name."},"Craft":{"first":"The binding thread is cut, not torn.","second":"Whoever took those pages took care."},"Aim":{"first":"There is one seat in this room that sees both doors.","second":"It is the one he says was hers."}}},{"t":"say","text":"…"},{"t":"challenge","title":"FIT THE PAGE","desc":"Your page came out of this book. Prove it, and find what else is on the leaf it came from.","options":[{"attr":"Intellect","verb":"match the hand, line by line, to the entries on either side"},{"attr":"Craft","verb":"match the torn edge to its stub, fibre to fibre"}],"reward":"+500g","fail":"it takes you the whole evening, with strangers watching you get it wrong"},{"t":"say","text":"You bring the candle close and try your page against the stubs, one after another. Then one of them takes it, every rag and fibre of the tear meeting its fellow. Your stub fits like a key. There are {N} stubs, and {N} of you.\n\n…","cond":{"on":"challenge","pass":true}},{"t":"say","text":"You try it against every stub but the right one. The candle burns down. The strangers watch you get it wrong. {F1}, in the end, reaches over and turns your page the other way up. It fits. There are {N} stubs, and {N} of you.","cond":{"on":"challenge","pass":false}},{"t":"press","title":"READ THE STUBS","detail":"what is left on the torn edges themselves","harder":4,"reward":"+200g, and one more detail"},{"t":"say","text":"Tilt them to the candle and you see it.\n\nEach stub has a faint straight line scored down it. She did not rip these out. She cut them against a rule, one at a time, with care.\n\nShe meant to send them.","cond":{"on":"press"}},{"t":"say","text":"So the list is hers. She wrote your names in a book, and cut them out, and then she stopped coming here. And each of you was set upon on the road, within the same few days, and came away holding a page."},{"t":"say","text":"On the facing leaf, one line will not give itself up to any of you. It is in some private shorthand, tight as wire. The longer you look at it, the less it says."},{"t":"act","label":"ASK HIM ABOUT THE LINE NOBODY CAN READ"},{"t":"say","text":"He does not look up from the bar.\n\n*\"That's a rock. Split lightning-wise, about so high. Two hours north.\"*\n\nHe goes on wiping.\n\n*\"She'd sit right there. I doubt she thought I was listening.\"*"},{"t":"say","text":"Once you know the place, the rest of the page gives way. It names none of you.\n\nIt is about a child. Taken, and held somewhere near that rock. No date. Only the place, and the plain sense, in every line of it, that whatever was happening there was not over."},{"t":"act","label":"ASK HIM TO TAKE YOU THERE"},{"t":"say","text":"He sets down the glass. In the quiet room it is the loudest thing there is.\n\n*\"I've a business to run.\"*"},{"t":"act","label":"TELL HIM NOBODY ELSE CAN READ HER"},{"t":"say","text":"A long pause. A log shifts in the grate and throws up a few sparks. He looks at the satchel, and the pages, and each of you in turn.\n\n*\"...As far as the Widow's Tooth. That's all I'm agreeing to.\"*"},{"t":"say","text":"You pay before you go up. {F2} puts down more than the cups were worth and nobody counts it. The innkeeper sweeps the coins into his apron without a word.\n\nThe fire has burned down to a red murmur. The extra cup is still at the empty end of the table. Nobody has touched it."},{"t":"say","text":"By the door, an old verse is carved into the beam, so old the wood has grown round the letters. Under it somebody has worked a small hollow into the timber."},{"t":"act","label":"FEEL INSIDE"},{"t":"say","text":"Cold enough to feel through the warm wood.\n\n**A locked Seeker Fragment has been added to your Chest.**","fragment":true},{"t":"say","text":"Upstairs, by a candle, you turn the notebook's last pages. The old house ticks and settles round you. Two lines in her hand, written years apart, in different inks:\n\n*\"Scattered on purpose, each piece safe alone. Only together do they mean anything.\"*\n\n*\"The old tellings of the Seekers speak of stones. The oldest records don't call them stones at all. They call them shards.\"*\n\nYou do not know what she meant. Somewhere below you, a door is barred for the night."},{"t":"say","text":"**First light. Two hours north. A child was held at that rock, and whatever it is has not finished.**","pull":true},{"t":"summary","lines":["**THE HOLLOW WAKE INN** · Day 2","You earned: `[gold]` · Intellect or Craft `[growth]`","You learned: the list is **Meira's**. She has been missing three weeks. Her last readable page is about a child held near a rock called the Widow's Tooth.","You hold: Meira's satchel and notebook","Fragment: 2 found","Tomorrow: **the Widow's Tooth, two hours north**"]}]}$json$::jsonb, $json${"dc":6,"wDef":22,"wAtk":15,"fightReward":0}$json$::jsonb),
('dark-moon', 1, 1, 3, $json${"week":1,"day":3,"title":"The Widow's Tooth","heading":"The Widow's Tooth","question":"is the child still at the rock?","steps":[{"t":"say","text":"Two hours north the road runs straight at a rock taller than a house, split down the middle as if something struck it once, long ago. You see it a long way off, black against a white sky. It does not get any friendlier as you come.\n\nIt is the first time the {N} of you have walked anywhere together. Garrick agreed to come as far as the Widow's Tooth and not a step further. In the two hours it takes to get there he has complained about the road, his boots and the weather, in that order, and seems to be enjoying himself.\n\nSomewhere along the way the question is put to him: how did he know this place from one line of scribble? He answers it to the air.\n\n*\"People tell a man with a cloth in his hand everything,\"* Garrick says. *\"They forget he's got ears.\"*"},{"t":"say","text":"There is nobody at the rock. Close to, it is dark with old rain and furred with grey lichen. The wind makes a low, hollow note in the split.\n\nThere are tracks at its foot: several people, not long ago, and a cart. The ruts run off toward deep bracken and a thread of smoke beyond; low on the stone, under the overhang, something has been cut into the rock where you would have to crouch with your back to the open ground to read it."},{"t":"choice","id":0,"labels":["GO TO THE MARKING","FOLLOW THE CART-RUTS"],"mode":"pick","branches":[{"options":[0],"text":"You crouch at the stone and put your fingers to the cut lines. They are cold, and gritty under your touch. In the deepest groove, kept dry by the overhang, a crumb of black charcoal comes away on your thumb. Somebody pressed paper to this stone not many days ago. That is where you are, with your back to the bracken, when the bracken moves.\n\n…","changed":"You found fresh charcoal in the cut stone · Your back was to the bracken: he strikes first.","roadFind":{"title":"Charcoal in the cut","text":"In the deepest groove of the cut stone at the Widow's Tooth, dry under the overhang, a crumb of black charcoal came away on your thumb. Somebody pressed paper to this stone not many days ago."}},{"options":[1],"text":"The ruts turn off the road toward a line of trees, and a thread of smoke beyond them. Where the left wheel sank deepest in the peat, a twist of grey reed-thatch has shaken loose from the cart-bed. You are looking that way, so you see him first: a man lying flat in the bracken, watching the rock.\n\n…","changed":"You found reed-thatch in the ruts · You spotted him in the bracken: you strike first.","roadFind":{"title":"Reed-thatch in the ruts","text":"Where the cart-ruts turned off toward the trees and the smoke, a twist of grey reed-thatch had shaken loose from the cart-bed into the peat."}}]},{"t":"notice","lines":{"Might":{"first":"The ruts are deep going in and shallow coming out.","second":"The cart left lighter than it came. Or it left something here."},"Agility":{"first":"The bracken is flattened in one place only.","second":"He has been lying there since before dawn."},"Intellect":{"first":"Nobody watches an empty rock.","second":"So it is not empty to him, or it will not be for long."},"Charm":{"first":"He is not afraid of you. He is afraid of being seen by you."},"Craft":{"first":"The cart has one wheel that pulls left.","second":"You would know its track again."},"Aim":{"first":"From where he lies he can see the road both ways and the village smoke.","second":"It is a post, and it has been used before."}}},{"t":"say","text":"…"},{"t":"fight","name":"THE MAN IN THE BRACKEN","desc":"He comes up running, and he is not running away.","firstLines":["You saw him first: you strike before he is set.","He was behind you: he strikes first."],"strikeFirst":{"on":"choice","choice":0,"options":[1]}},{"t":"say","text":"He does not say a word. Not when he is hit, and not when he hits. The moment there is a gap he takes it, and he is away through the trees toward the smoke, faster than any of you.\n\n{F3} goes twenty yards after him and stops. {F3} stands there a moment longer, listening, then turns back."},{"t":"say","text":"You had him by the collar for a moment, close enough to smell him. Woodsmoke, and lamp oil.","cond":{"on":"fight","won":true}},{"t":"say","text":"You are still sitting in the crushed bracken when {F3} gets back, with the wind knocked clean out of you and a bruise coming up along your ribs that you will feel for days.","cond":{"on":"fight","won":false}},{"t":"say","text":"You go back to the rock.\n\nSomebody takes the burned scrap from the forest road out of a pocket, and holds it against the marking.\n\nIt fits. Every raised line sits under its line of charcoal, and there is charcoal still, ground into the edges of the stone. She laid her paper here and rubbed. This rock is what the scrap is a picture of.\n\nFor a moment nobody says anything. The wind goes on sounding its one low note in the split.\n\nMeira stood where you are standing. And the man who came at you on the forest road was carrying her work."},{"t":"say","text":"Under the overhang, on a dry shelf out of the wind, something small is lying on its side."},{"t":"act","label":"PICK IT UP"},{"t":"say","text":"A carved horse, no longer than your thumb. It is grey with a winter or two of weather. Its edges have gone soft, the way wood does when it has been held a great deal and then not held at all.\n\nIt is a child's. It has been here a long time."},{"t":"say","text":"There is a crack in the stone under the marking, wide enough for a hand."},{"t":"act","label":"REACH IN"},{"t":"say","text":"The same cold. The same weight.\n\n**A locked Seeker Fragment has been added to your Chest.**","fragment":true},{"t":"say","text":"The morning is getting on, and this is the Widow's Tooth. Garrick has not gone back to his inn. He is standing in the road with his pack on, looking at the smoke.\n\n**The ruts go that way. So did the man. He will be there before you, and every door will be shut when you come.**","pull":true},{"t":"summary","lines":["**THE WIDOW'S TOOTH** · Day 3","You earned: `[gold]`","You learned: nobody is here. But **Meira made her rubbing at this rock**, and a child was kept here once.","You hold: a small carved horse","Fragment: 3 found","Tomorrow: **Fenmark, where the cart went**"]}]}$json$::jsonb, $json${"dc":6,"wDef":22,"wAtk":15,"fightReward":300}$json$::jsonb),
('dark-moon', 1, 1, 4, $json${"week":1,"day":4,"title":"Fenmark","heading":"Fenmark, where the cart went","question":"what happened in this village, and why will nobody say?","steps":[{"t":"say","text":"Fenmark sits low at the edge of the fen: reed thatch and peat smoke, along a single lane of cobbles with mud between. It goes quiet the moment you come down the lane. Doors do not quite shut. Nobody is standing in one, either.\n\nThe lookout from the rock came through here ahead of you. You can tell by the gate at the far end of the street, left swinging. It knocks softly on its post in the wind.\n\n{F1} takes the left side of the lane, {F2} the right. You take the well."},{"t":"say","text":"Behind the well, on an upturned bucket: a bowl of barley, half eaten, the spoon still standing in it. You hold your hand over it. It is still warm.\n\nWhoever was eating it left in a hurry, and not long ago.\n\n…"},{"t":"notice","lines":{"Might":{"first":"The bucket was not knocked over. It was set down.","second":"Whoever sat here is small, and careful."},"Agility":{"first":"One heel-mark in the mud, deep at the toe. They went at a run.","second":"Toward the back lanes, not the road."},"Intellect":{"first":"Barley and nothing else, in a house bowl. This is somebody's ordinary dinner.","second":"They live here, and they did not expect to be found."},"Charm":{"first":"Every shutter on the street is closed but one.","second":"Somebody wants to be asked."},"Craft":{"first":"The spoon is whittled, not bought, and whittled badly.","second":"A child's knife did that."},"Aim":{"first":"From this bucket you can see the whole lane and nobody in the lane can see you.","second":"It was chosen for watching."}}},{"t":"choice","id":0,"labels":["LOOK FOR FOOTPRINTS","KNOCK NEXT DOOR"],"mode":"pick","branches":[{"options":[0],"text":"You crouch by the bucket. The mud there has been trodden by every boot in Fenmark, but over the top of it all runs a line of small prints, quick and light, too short in the stride for any grown man. Where they turn between the sheds, a thread of unhemmed grey wool has caught on a nail at the height of a boy's elbow. They go off between the sheds behind the lane, and there you lose them.\n\n…","changed":"You took the back lanes (Agility roll on the Challenge) and found grey wool on the shed nail.","roadFind":{"title":"Grey wool on the nail","text":"Where the small footprints turned between the sheds behind the well, a thread of unhemmed grey wool was caught on a nail at the height of a boy's elbow."}},{"options":[1],"text":"The door beside the well opens the width of a hand before your knuckles have finished on it. An eye, a grey braid, a thin hand on the latch. Behind her in the dim kitchen, a pot of the same boiled barley is still steaming on the hob — she is the one who filled the bowl by the well. She does not speak, and she does not shut it. Her gaze goes once, quickly, down the lane and back to you.\n\n…","changed":"You knocked next door (Charm roll on the Challenge) and saw the neighbour's barley pot.","roadFind":{"title":"The second barley pot","text":"Inside the neighbour's half-open door beside the well, a pot of the same boiled barley was still steaming on the hob. Someone in Fenmark was feeding the boy on the quiet."}}]},{"t":"challenge","title":"FIND WHO LEFT IT","desc":"Somebody in this village watched something, and is hiding from you. Find them before the whole street knows you are looking.","options":[{"attr":"Agility","verb":"follow the fresh prints round the back lanes"},{"attr":"Charm","verb":"coax the neighbour at her half-open door into pointing"}],"reward":"+500g","fail":"you search the wrong end of the village first, in full view"},{"t":"say","text":"The prints are small and quick, and they double back twice. You do not follow them. You walk round the grain store the other way, sit down on the step in the thin sun, and wait.\n\nAfter a while a boy of about fourteen edges out of the gap behind it, all elbows and held breath. He has seen you see him. He does not run.","cond":{"on":"challenge","pass":true}},{"t":"say","text":"You try three doors on the wrong side of the street, and three faces watch you do it through the cracks. By the time you think of the grain store the boy has bolted from behind it, straight into {F3}, who was coming the other way.\n\nHe is shaking. {F3} lets go of his sleeve and steps back.","cond":{"on":"challenge","pass":false}},{"t":"say","text":"He looks at each of you in turn. He is counting you."},{"t":"choice","id":1,"labels":["SHOW HIM THE LIST","ASK WHO WAS TAKEN","SAY NOTHING. WAIT."],"mode":"pick","branches":[{"options":[0],"text":"You unfold Meira's list and hold it where he can see. He reads it slowly, his lips moving, then looks up from the names to your faces, one after another, as if to make sure you are the people written there. Something in his shoulders lets go.\n\n*\"She was here,\"* he whispers, touching the corner of the leaf with one dirty finger. *\"The woman with the satchel. Two weeks back. She asked about the split stone, and she had a book of that same paper.\"*","changed":"You showed him Meira's list — he recognized her paper from two weeks ago.","roadFind":{"title":"The woman with the satchel","text":"The boy at the well recognized the paper of Meira's list. He says a woman with a satchel and a book of that same paper came through Fenmark two weeks back, asking about the split stone."}},{"options":[1],"text":"You ask him straight out who they took. His chin comes up at that. For three days Fenmark has told him only to keep quiet, and nobody has asked him anything at all.\n\n*\"Her mother's shut inside with the shutters barred,\"* he says, his voice tight. *\"They told her if she cried out or went to the road, they'd never bring her back.\"*","changed":"You asked straight out who was taken — you learned how they silenced Tamsin's mother.","roadFind":{"title":"How they kept Fenmark quiet","text":"The boy at the well says Tamsin's mother is shut behind barred shutters: the men who took Tamsin warned that if anyone cried out or went to the road, they would never bring her back."}},{"options":[2],"text":"You say nothing. You lean on the cold lip of the well and let the quiet be, as if you had the whole afternoon to spend on it. The boy watches you do it. He had braced himself for questions.\n\nBecause you do not press him, his eyes go where his thoughts are: down the lane to the swinging gate, and then to the third house on the left, where a child's stool still sits under an open shutter.","changed":"You waited in silence — his gaze gave away Tamsin's house and the gate they used.","roadFind":{"title":"Where the boy looked","text":"Given silence at the well, the boy looked first to the third house on the left — where a child's stool sits under the open shutter — and then to the swinging gate at the fen end of the lane."}}]},{"t":"say","text":"For a while he says nothing at all. He looks once down the empty lane. Then it comes out low and fast.\n\n*\"Three nights ago. They came in the dark with no torches. They did not knock anything over. They did not say anything they did not have to. Like they'd done it before.\"*\n\n*\"They took Tamsin. She's nine. She was counting when they carried her out. She counts when she's frightened.\"*\n\nHe swallows.\n\n*\"One of them had a knife I'd never seen the like of. Curved. Black handle. He saw me at the window. He did not even walk faster. He just said they'd know if I talked.\"*"},{"t":"say","text":"While he talks he hums, without noticing, a rhyme with no tune to speak of. His grandmother's, he says. She sang it here, at the well.\n\nYou look at the well. Its stone lip is older than every house in the street, green-black and sweating with damp. Worn into it, just where a hand would rest, is a hollow."},{"t":"act","label":"REACH IN"},{"t":"say","text":"Your fingers close on something thin and cold. Well-water beads on it and will not soak in.\n\n**A locked Seeker Fragment has been added to your Chest.**","fragment":true},{"t":"say","text":"Boots on the cobbles.\n\nAn old man is coming down the street with two younger ones behind him, and the two younger ones walk straight past him and stand between you and the well."},{"t":"say","text":"The boy is still standing next to you. He does not move away.","cond":{"on":"challenge","pass":true}},{"t":"say","text":"The boy is behind {F3}. One of the men looks at him, and he looks at the ground.","cond":{"on":"challenge","pass":false}},{"t":"choice","id":2,"labels":["STAND WHERE YOU ARE","STEP BACK, HANDS OPEN","PUT YOURSELF IN FRONT OF THE BOY"],"mode":"pick","branches":[{"options":[0],"text":"You stay exactly where you are, your feet set on the wet cobbles. The two younger men had expected you to give ground. They glance at the elder, and do not quite know what to do with their hands. Close to, you see that neither of them carries so much as a hedging bill at his belt — they came out with bare hands, hoping numbers alone would turn you from the lane.","changed":"You held your ground — you saw the young men came out unarmed, bluffing to turn you back.","roadFind":{"title":"Unarmed men","text":"When you stood your ground at the well, the two younger men had nothing at their belts — not even a hedging bill. Fenmark came out to bluff you away, not to fight."}},{"options":[1],"text":"You take one slow step back and let them see your empty hands. The nearer of the two young men lets out a breath, and some of the stiffness goes out of the street. As his shoulders drop, his cuff rides up: there is a dark bruise round his wrist, three days old, where a hand gripped him hard when he tried to come out of his door that night.","changed":"You stepped back with open hands — you saw the three-day bruise on the young man's wrist.","roadFind":{"title":"The bruised wrist","text":"When the nearer young man lowered his guard, his cuff showed a dark bruise round his wrist, three days old — someone held him back when Tamsin was taken."}},{"options":[2],"text":"You step across, between the men and the boy. It is a small movement, and every eye in the lane follows it. The elder's face changes. For a moment he looks less like a man guarding his village than a man ashamed of it. Behind your shoulder, the boy breathes one thing more before the elder reaches you: *\"They didn't bring a lantern. They knew where the step was.\"*","changed":"You stood in front of the boy — he whispered that the men knew the steps of Fenmark in the dark.","roadFind":{"title":"No lantern in the dark","text":"From behind your shoulder in the standoff, the boy whispered one detail more: the men who came in the dark carried no lantern, yet knew where every step in the lane was."}}]},{"t":"say","text":"Nobody draws. Nobody needs to. The message is plain enough.\n\nThe elder says the things an elder says: that Fenmark has no quarrel with travellers, that the road out is the same as the road in.\n\nBut you are watching his hands, and his hands are not angry. They are afraid. He is not hiding what happened here. He is terrified of what happens to this village if it is known that somebody talked.\n\nHe steps in close, as if to see you off. His voice drops until only you can hear it. His breath smells of peat smoke and no sleep.\n\n*\"Please. There's a woman two hours east who's seen that same curved blade before. Ask her. Don't say I sent you.\"*\n\nThen, louder, for the street: *\"Go on, now.\"*"},{"t":"say","text":"Garrick is already holding the gate at the bottom of the lane. He has found the one dry place to stand in all of Fenmark, and he looks as if he would like you to notice.\n\nThe boy catches up with you there, out of breath.\n\n*\"A man ran through at first light. He did not stop for anyone. He took the east path.\"*"},{"t":"say","text":"It is long past noon when Fenmark lets you go, and the light is already thinning over the fen. Behind you, one by one, the shutters close.\n\n**East. Two hours. He has half a day on you, and he is heading for the only other person alive who has seen that knife.**","pull":true},{"t":"summary","lines":["**FENMARK** · Day 4","You earned: `[gold]` · Agility or Charm `[growth]`","You can now afford: `[what your gold now buys]`","You learned: her name is **Tamsin**. Nine years old. Taken three nights ago by quiet men; one carries a curved, black-handled knife.","Fragments: 4 found","Tomorrow: **the old charcoal camp, two hours east**"]}]}$json$::jsonb, $json${"dc":6,"wDef":22,"wAtk":15,"fightReward":0}$json$::jsonb),
('dark-moon', 1, 1, 5, $json${"week":1,"day":5,"title":"The old charcoal camp","heading":"East, to the charcoal camp","question":"who has seen the curved knife, and what happened that time?","steps":[{"t":"say","text":"The camp is an old one: burning-pits long cold, a trade that left years ago. The earth is black to a spade's depth. When the wind stirs it, the whole clearing smells of a fire that went out before you were born. But the path in is worn too clean for that to be all of it.\n\nYou reach it after dark. At the edge of the clearing stands a shed, with no light in it. You knock. Nobody answers. If the runner from Fenmark came this way, he had half a day on you; the step and the firepit are right at your feet, while the path in runs back toward the dark trees."},{"t":"choice","id":0,"labels":["LOOK AT THE STEP","LOOK AT THE FIRE","LOOK AT THE PATH"],"mode":"pick","branches":[{"options":[0],"text":"Swept this morning. Somebody lives here, and is proud enough to sweep. Tucked under the threshold stone is a narrow line of dry salt and grey rowan-ash — an old hill-country ward laid down by someone who expects a visitor back. You are still crouched by the door when a blade works into the shutter behind the shed.\n\n…","changed":"You found her rowan-ash ward at the step · You were at the front door: the runner strikes first.","roadFind":{"title":"Salt and rowan-ash","text":"Under the swept threshold stone of the charcoal-burner's shed lay a line of dry salt and rowan-ash: an old hill ward laid by someone waiting for a bad visitor to return."}},{"options":[1],"text":"Cold on top. Warm underneath, when you push a hand into the ash. Banked, not dead. Somebody means to come back to it. Set on the flat stone beside the pit is a tin cup of herb-tea with the steam barely off it — she slipped into the trees only minutes before your boots came up the road. You are still kneeling by the ash when a blade works into the shutter behind the shed.\n\n…","changed":"You found her warm cup by the banked fire · You were at the firepit: the runner strikes first.","roadFind":{"title":"The warm pannikin","text":"Beside the banked firepit stood a tin cup of herb-tea barely cool. The woman of the camp slipped into the trees only minutes before you reached the clearing."}},{"options":[2],"text":"Two sets of prints on it, both fresh. A woman's, going out. And over them a man's, coming in, at a run. His stride is long and low, and the mud at the turn is still oozing water into the heel-mark.\n\nHe is here.\n\n…","changed":"You read the fresh prints on the path · You knew he was here: you strike first.","roadFind":{"title":"Prints at a run","text":"On the path into the charcoal camp, a man's running prints overlay the woman's outgoing ones, the mud still oozing water into the heel-marks. He reached the clearing just ahead of you."}}]},{"t":"notice","lines":{"Might":{"first":"The axe is gone from the block. The block is still wet.","second":"Whoever lives here took it with them, and not for wood."},"Agility":{"first":"A shed with one door and a shuttered back window.","second":"Somebody inside it could be gone before you knocked twice."},"Intellect":{"first":"Nobody keeps a place this tidy and this hidden unless they are waiting for something."},"Charm":{"first":"There is one bowl, one cup, one stool.","second":"She has been alone a long time."},"Craft":{"first":"The shutters bar from the inside and the outside both.","second":"She built this to be watched from."},"Aim":{"first":"There is a gap in the trees that frames the whole clearing.","second":"You are being looked at through it now."}}},{"t":"say","text":"Something moves behind the shed. You hear a blade being worked into wood, and then a breath, held too late.\n\n…"},{"t":"fight","name":"THE RUNNER FROM FENMARK","desc":"He got here first. He is trying the shutters.","firstLines":["You read the path: you are ready for him.","He hears you before you see him."],"strikeFirst":{"on":"choice","choice":0,"options":[2]}},{"t":"say","text":"The same silence. The same way of leaving: the first gap, and gone, north through the trees this time.\n\n{F1} has a hand on {F2}'s arm, to stop {F2} following into the dark. {F2} does not shake it off."},{"t":"say","text":"He has left his knife behind, stuck in the shutter where he was working it. A plain kitchen knife. There is nothing curved about it.","cond":{"on":"fight","won":true}},{"t":"say","text":"Your shoulder is against the shed wall where he threw you, and the boards are rough and cold through your shirt. It is a while before your hands stop shaking.","cond":{"on":"fight","won":false}},{"t":"say","text":"A twig goes.\n\nShe is at the edge of the trees, where the starlight gives out, and she has been there for some time. A woman with a woodcutter's axe held low and ready, and her eyes going from face to face.\n\n*\"Which of you carries the curved knife?\"*"},{"t":"choice","id":1,"labels":["SHOW HER YOUR EMPTY HANDS","TELL HER WHO YOU JUST DROVE OFF","HOLD OUT THE CARVED HORSE"],"mode":"pick","branches":[{"options":[0],"text":"The axe comes down by inches. As she lowers it, the starlight catches a fresh white gouge in the ash-wood helve — he came at her among the trees before he ever tried her shutter, and she turned his blade with the haft. Then her eyes go to the carved horse in your other hand, and stop.","changed":"You showed empty hands — you saw the fresh blade-nick on her axe-helve from the trees.","roadFind":{"title":"The nicked axe-helve","text":"When the woman at the charcoal camp lowered her axe, the haft showed a fresh white gouge where she had turned a knife-blow in the trees before you arrived."}},{"options":[1],"text":"The axe comes down by inches. At the word of the man at her shutter, her eyes flick once, sharply, to the flat root-cellar stone behind the woodpile before coming back to your face — whatever she keeps hidden here, it is under that stone and not in the shed. Then her eyes go to the carved horse in your other hand, and stop.","changed":"You told her who you drove off — her glance gave away the root-cellar stone behind the woodpile.","roadFind":{"title":"The root-cellar stone","text":"When told a man had been prizing at her back shutter, the woman glanced once at the flat root-cellar stone behind the woodpile — her real hiding-place is under the woodpile, not inside the shed."}},{"options":[2],"text":"The axe comes down all at once. Before she even asks your names, her fingers go to her belt, unfasten a small river-stone charm bound in iron wire — kept since the winter the boy was taken — and press it into your palm as she takes the little horse from you.","changed":"You knew the carved horse was hers and held it out first — she trusted you at once (+1 Might Relic).","roadFind":{"title":"The carver's charm","text":"Held out without a word, the carved horse from the Widow's Tooth brought her axe down at once. She pressed an iron-bound river-stone charm into your hand before she sat."},"relic":"Might"}]},{"t":"say","text":"She takes the little horse in both hands. She has to sit.\n\nGarrick builds the fire up without being asked. He coaxes the banked coals until they catch, and the clearing jumps into orange light. Then he puts a cup into her hands. She holds it as if it were the first warm thing she has touched in a month.\n\n*\"That's my sister's boy's,\"* she says. *\"I carved it.\"*"},{"t":"say","text":"For a while there is only the fire. Then it comes, all of it, two winters' worth.\n\n*\"Curved. Black-handled. I know it. Same man took him two winters back. Same time of year. Same stretch of country. Nobody ever found him.\"*\n\nShe turns the horse over.\n\n*\"Where was it?\"*\n\nYou tell her. She nods, slowly, as if she had always known the rock."},{"t":"say","text":"You count it out, because somebody has to.\n\nMeira has been gone three weeks. Tamsin was taken this week. The child in Meira's notes, held near the rock, cannot be Tamsin.\n\nMeira was writing about this woman's nephew. About the last one.\n\nAnd it is the same time of year."},{"t":"say","text":"The fire ticks and settles. She says a thing twice while she talks, hardly hearing herself: *\"The power that gives is also the power that takes.\"* She cannot say where she first heard it. Her eyes go, when she says it, to the old dead tree behind the shed, hollow at the foot."},{"t":"act","label":"REACH INTO THE HOLLOW"},{"t":"say","text":"Wrapped in something long since rotted to threads. They give way under your fingers with a dry whisper, and what is inside is still cold.\n\n**A locked Seeker Fragment has been added to your Chest.**","fragment":true},{"t":"say","text":"Nobody sleeps much. At first light she walks you to the edge of the camp, and stands on the old charcoal road, grey with frost and ash, and points.\n\n**North. The same man, the same country, the same season. If it comes round like a calendar, the time is now.**","pull":true},{"t":"summary","lines":["**THE OLD CHARCOAL CAMP** · Day 5","You earned: `[gold]`","You learned: **it has happened before.** The same man took a boy from this country two winters ago, at this time of year. He is the child in Meira's notes.","Fragment: 5 found","Tomorrow: **the ford, on the old charcoal road north**"]}]}$json$::jsonb, $json${"dc":6,"wDef":22,"wAtk":15,"fightReward":300}$json$::jsonb),
('dark-moon', 1, 1, 6, $json${"week":1,"day":6,"title":"The ford","heading":"North, to the ford","question":"where did they take her?","steps":[{"t":"say","text":"By midday the old charcoal road comes down to a river. It is shallow enough to wade, but brown and fast and full of the hills' rain. It talks to itself over the stones. A worn stone stands at the edge to show the safe line across.\n\nThe near bank is churned to mud. A cart went over: its ruts come out on the far side and go on.\n\nOne set of prints does not. Small ones. They come down to the water's edge and stop.\n\nThe river is rising. The edge of the mud is going as you watch, crumb by crumb.\n\n…"},{"t":"notice","lines":{"Might":{"first":"The cart sat low coming down the bank.","second":"It rides high on the far side."},"Agility":{"first":"The small prints are evenly spaced.","second":"Nobody was dragging her. Not yet."},"Intellect":{"first":"A cart that crosses and a child who does not.","second":"They parted here on purpose."},"Charm":{"first":"{F2} has stopped talking. Everybody has."},"Craft":{"first":"The left wheel pulls.","second":"It is the cart from the Widow's Tooth."},"Aim":{"first":"On the far bank, nothing small.","second":"Not one print."}}},{"t":"say","text":"…"},{"t":"challenge","title":"READ THE WATERLINE","desc":"The river is taking the prints. Whatever they say, they will say it once.","options":[{"attr":"Aim","verb":"pick out the line of them from the bank before it goes"},{"attr":"Agility","verb":"get down the bank to the water's edge, and read them close before the river takes the rest"}],"reward":"+500g","fail":"the water takes them, and you will never know how she came to it"},{"t":"say","text":"You have them. Small prints, walking, right to the edge. Her own feet. She was not hurt, and she was not carried here.\n\nThen two deep prints facing her, a man's, with the heels dug in. He lifted her. And after that there is only water.\n\n…","cond":{"on":"challenge","pass":true}},{"t":"say","text":"A brown tongue of river slides over the mud, and when it draws back the mud is smooth. There were prints. Now there is the cart, and nothing.\n\n{F3} finds the last of it, further down: two deep heel-marks, a man's, facing the water. He lifted something. After that there is only water.","cond":{"on":"challenge","pass":false}},{"t":"press","title":"WADE OUT","detail":"find where they went from the water","harder":4,"reward":"+200g, and one more detail"},{"t":"say","text":"The cold takes you at the knees, then at the waist. The current leans its whole weight on you.\n\nMid-stream, on the upstream side of the ford-stone, a scrape of fresh paint on the rock at the height of a gunwale.\n\nThere was a boat.","cond":{"on":"press"}},{"t":"say","text":"She was carried into the river. The cart went on without her. No tracker alive can follow from here."},{"t":"say","text":"Under the waterline, at the foot of the ford-stone, where you would only see it in a low year:"},{"t":"act","label":"REACH DOWN"},{"t":"say","text":"Cold beyond the cold of the river.\n\n**A locked Seeker Fragment has been added to your Chest.**","fragment":true},{"t":"say","text":"That is six.\n\nSix of these old scraps in a week, some of them hidden longer than anyone can say, and not one of you has missed one. You have been putting them in your pockets like a child picking up stones.\n\nMeira wrote it: *each piece safe alone. Only together do they mean anything.*"},{"t":"act","label":"LAY THEM OUT"},{"t":"say","text":"You set them side by side on a flat rock, still warm from the noon sun. The river is loud beside you.\n\nThey move.\n\nNot far. The width of a finger. Each one turns a little, and settles against the next, as if they had been waiting for exactly this and exactly these hands. And then they are not six things. They are one.\n\nA map. Old, and exact, in a hand none of you knows.\n\nIt runs across the ford and on. And the place it ends is marked with a shape.\n\n{F1} puts the burned rubbing down beside it, and squares its edge to the map's with one finger.\n\nThe same shape."},{"t":"say","text":"For a long moment nobody touches either of them. The trail you have lost and the map you are holding point the same way."},{"t":"say","text":"That night you stop at a roadside inn, a smoky, crowded place of drovers and dogs. A ham hangs in the chimney. Garrick orders for the table. When the cups come he pours one more than there are of you, and sets it at the empty place."},{"t":"act","label":"ASK WHO IT IS FOR"},{"t":"say","text":"*\"Family habit. We always pour one for whoever can't be with us.\"*"},{"t":"say","text":"Over supper the way has to be got by heart, and there is only one way to do that. There is one map, and there are {N} of you."},{"t":"choice","id":0,"labels":["READ IT OUT","LET {F2} READ IT"],"mode":"pick","branches":[{"options":[0],"text":"You smooth the map flat between the cups and read it yourself, tracing each line with a fingertip so the others can follow it, from the ford all the way to the mark. Right at the mark, your fingertip catches on a tiny pin-hole punched clean through the old vellum — somebody once pinned this very spot to a board before the map was cut in six.","changed":"You read the map out yourself — your fingertip found an old pin-hole punched through the mark.","roadFind":{"title":"The pin-hole at the mark","text":"Tracing the assembled map by fingertip over supper, you felt a tiny pin-hole punched right through the mark beyond the ford, from before the map was ever cut in six."}},{"options":[1],"text":"You turn the map round and slide it across to {F2}, who reads it the way some people read a letter from home: slowly, frowning a little, as if the words might change if they were hurried. Because your own eyes are not on the parchment, you catch a man in a riding-cloak by the chimney stopping with his mug halfway to his mouth when {F2} names the bend above the ford.","changed":"You let {F2} read the map — with your eyes on the room, you caught the courier listening at the mention of the ford.","roadFind":{"title":"The listening courier","text":"While your friend read the map aloud in the roadside inn, a man in a riding-cloak by the chimney held his mug still at the mention of the bend above the ford, then paid his bill without taking a bed."}}]},{"t":"say","text":"It is read out, twice, slowly, so that everybody has it. The room is loud enough that you all lean in close to hear.\n\nAcross the room a courier who came in for a bed settles his bill without taking one. He is gone within the hour."},{"t":"say","text":"**Cross at first light. You will be there by nightfall. Whatever is at the place the map marks, the season for it is now.**","pull":true},{"t":"summary","lines":["**THE FORD** · Day 6","You earned: `[gold]` · Aim or Agility `[growth]`","You learned: she was carried into the river and the trail ends. **The six fragments are a map**, and it ends at the mark from Meira's rubbing.","*On a failure:* You missed something at the ford. Someone at the fire may have seen it.","You hold: the map","Fragments: 6 of 6 · the map is whole","Tomorrow: **THE GATHERING** · across the ford, together"]}]}$json$::jsonb, $json${"dc":6,"wDef":22,"wAtk":15,"fightReward":0}$json$::jsonb)
on conflict (series_id, season_number, week, day) do update set script = excluded.script, meta = excluded.meta;

-- Piece E2 (21 Oct 2026): Week 1's 7 forks as readable trades, Fit Challenge attribute lock,
-- discernment Relic reward (+1 Might Relic on W1D5 "HOLD OUT THE CARVED HORSE"), and road finds carried to the fire.

-- 1. Allow fork road finds ('fork:<choice_id>:<branch_idx>') in fire_laid.kind
alter table public.fire_laid drop constraint if exists fire_laid_kind_check;
alter table public.fire_laid add constraint fire_laid_kind_check
  check (kind in ('pass', 'press') or kind like 'fork:%');

-- 2. Helper: return road-find pieces from forks chosen on (p_week, p_day) by any member of p_party
create or replace function public.fire_fork_pieces_for(p_party uuid, p_week int, p_day int)
returns table(key text, title text, body text, user_id uuid, character_name text, at timestamptz)
language sql stable security definer set search_path = '' as $$
  with script as (
    select c.script -> 'steps' as steps
    from public.chapters c
    join public.parties p on p.series_id = c.series_id and p.season_number = c.season_number
    where p.id = p_party and c.week = p_week and c.day = p_day
  ),
  choice_branches as (
    select
      (s.val ->> 'id')::int as choice_id,
      (b.ord - 1)::int as branch_idx,
      b.val as branch
    from script,
      jsonb_array_elements(coalesce(script.steps, '[]'::jsonb)) as s(val),
      jsonb_array_elements(coalesce(s.val -> 'branches', '[]'::jsonb)) with ordinality as b(val, ord)
    where s.val ->> 't' = 'choice'
      and jsonb_typeof(b.val -> 'roadFind') = 'object'
  )
  select
    'fork:' || cb.choice_id || ':' || cb.branch_idx as key,
    cb.branch -> 'roadFind' ->> 'title' as title,
    cb.branch -> 'roadFind' ->> 'text' as body,
    md.user_id,
    m.character_name,
    coalesce(md.finished_at, md.opened_at, now()) as at
  from public.member_days md
  join public.party_members m on m.party_id = md.party_id and m.user_id = md.user_id
  join choice_branches cb on exists (
    select 1
    from jsonb_array_elements_text(coalesce(md.picks -> (cb.choice_id::text), '[]'::jsonb)) as p(opt_txt)
    join jsonb_array_elements_text(coalesce(cb.branch -> 'options', '[]'::jsonb)) as bo(opt_txt)
      on bo.opt_txt = p.opt_txt
  )
  where md.party_id = p_party and md.week = p_week and md.day = p_day
    and coalesce(cb.branch -> 'roadFind' ->> 'title', '') <> ''
    and coalesce(cb.branch -> 'roadFind' ->> 'text', '') <> '';
$$;

-- 3. pick_choice: keep 'pick' forks single-choice and award branch relic (e.g. +1 Might Relic on W1D5)
create or replace function public.pick_choice(p_party uuid, p_choice int, p_option int) returns void
language plpgsql security definer set search_path = '' as $$
declare
  v_week int;
  v_day int;
  v_picks jsonb;
  v_step jsonb;
  v_branch jsonb;
  v_relic text;
  v_have int;
begin
  select o_week, o_day into v_week, v_day from public.my_today_row(p_party);

  select picks into v_picks
  from public.member_days
  where party_id = p_party and user_id = auth.uid() and week = v_week and day = v_day and finished_at is null
  for update;

  if not found then return; end if;

  select s into v_step
  from public.chapters c
  join public.parties p on p.series_id = c.series_id and p.season_number = c.season_number
  cross join lateral jsonb_array_elements(c.script -> 'steps') s
  where p.id = p_party and c.week = v_week and c.day = v_day
    and s ->> 't' = 'choice' and (s ->> 'id')::int = p_choice
  limit 1;

  -- For 'pick' mode forks, only one option can be chosen
  if v_step is not null and (v_step ->> 'mode') = 'pick' then
    if jsonb_array_length(coalesce(v_picks -> p_choice::text, '[]'::jsonb)) > 0 then
      return;
    end if;
  end if;

  if coalesce(v_picks -> p_choice::text, '[]'::jsonb) @> to_jsonb(p_option) then
    return;
  end if;

  update public.member_days
  set picks = jsonb_set(picks, array[p_choice::text], coalesce(picks -> p_choice::text, '[]'::jsonb) || to_jsonb(p_option))
  where party_id = p_party and user_id = auth.uid() and week = v_week and day = v_day and finished_at is null;

  -- If the chosen branch grants a discernment Relic (e.g. W1D5 "HOLD OUT THE CARVED HORSE" -> Might), award +1 Relic once
  if v_step is not null then
    for v_branch in
      select b
      from jsonb_array_elements(coalesce(v_step -> 'branches', '[]'::jsonb)) b
      where coalesce(b -> 'options', '[]'::jsonb) @> to_jsonb(p_option)
    loop
      v_relic := v_branch ->> 'relic';
      if v_relic is not null and public.relic_kind_ok(v_relic) then
        select coalesce((relics ->> v_relic)::int, 0) into v_have
        from public.member_progress
        where party_id = p_party and user_id = auth.uid()
        for update;
        update public.member_progress
        set relics = jsonb_set(coalesce(relics, '{}'::jsonb), array[v_relic], to_jsonb(coalesce(v_have, 0) + 1), true)
        where party_id = p_party and user_id = auth.uid();
      end if;
    end loop;
  end if;
end;
$$;

-- 4. roll_card: enforce Fit fork Challenge attribute lock when a 'pick' fork immediately precedes the Challenge card
create or replace function public.roll_card(p_party uuid, p_attr text, p_relic boolean) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_week int; v_day int; v_step jsonb; v_meta jsonb; v_dc int; v_score int; v_bonus int; v_relic int := 0; v_d20 int; v_net int;
  v_pass boolean; v_growth int := 0; v_played int; v_base int; v_result jsonb;
  v_steps jsonb; v_idx int; v_prev_step jsonb; v_picks jsonb; v_fit_opt int; v_forced_attr text;
begin
  select o_week, o_day into v_week, v_day from public.my_today_row(p_party);
  if (select challenge from public.member_days where party_id = p_party and user_id = auth.uid() and week = v_week and day = v_day) is not null then
    raise exception 'already rolled';
  end if;
  v_step := public.today_step(p_party, v_week, v_day, 'challenge');

  -- Check if a 'pick' Fit fork immediately precedes the Challenge card in today's chapter
  select c.script -> 'steps' into v_steps
  from public.chapters c
  join public.parties p on p.series_id = c.series_id and p.season_number = c.season_number
  where p.id = p_party and c.week = v_week and c.day = v_day;

  select (ord - 1)::int into v_idx
  from jsonb_array_elements(coalesce(v_steps, '[]'::jsonb)) with ordinality as t(elem, ord)
  where elem ->> 't' = 'challenge'
  limit 1;

  if v_idx is not null and v_idx > 0 then
    v_prev_step := v_steps -> (v_idx - 1);
    if (v_prev_step ->> 't') = 'choice'
       and (v_prev_step ->> 'mode') = 'pick'
       and jsonb_array_length(coalesce(v_prev_step -> 'labels', '[]'::jsonb)) = jsonb_array_length(coalesce(v_step -> 'options', '[]'::jsonb))
    then
      select picks into v_picks
      from public.member_days
      where party_id = p_party and user_id = auth.uid() and week = v_week and day = v_day;

      if jsonb_array_length(coalesce(v_picks -> (v_prev_step ->> 'id'), '[]'::jsonb)) > 0 then
        v_fit_opt := (v_picks -> (v_prev_step ->> 'id') ->> 0)::int;
        v_forced_attr := v_step -> 'options' -> v_fit_opt ->> 'attr';
        if v_forced_attr is not null then
          p_attr := v_forced_attr;
        end if;
      end if;
    end if;
  end if;

  if v_step is null or not exists (select 1 from jsonb_array_elements(v_step -> 'options') o where o ->> 'attr' = p_attr) then
    raise exception 'not today''s Challenge';
  end if;
  if public.day_open_step(p_party, auth.uid(), v_week, v_day) <> 'card' then raise exception 'not yet'; end if;
  if p_relic then
    perform public.spend_relic(p_party, p_attr);
    v_relic := 4;
  end if;
  v_meta := public.today_meta(p_party, v_week, v_day);
  v_dc := (v_meta ->> 'dc')::int
          + case when v_step ? 'harderIf' and (public.party_claims(p_party) ? (v_step -> 'harderIf' ->> 'key')) = (v_step -> 'harderIf' ->> 'has')::boolean
                 then (v_step -> 'harderIf' ->> 'by')::int else 0 end;
  select (attrs ->> p_attr)::int into v_score from public.member_progress where party_id = p_party and user_id = auth.uid();
  v_bonus := public.tier_bonus(v_score);
  v_d20 := public.d20();
  v_net := v_d20 + v_bonus + v_relic - v_dc;
  v_pass := v_net >= 1;
  if v_pass then
    if 1 + v_bonus - v_dc < 1 and 20 + v_bonus - v_dc >= 1 then
      select count(*) + 1 into v_played from public.member_days
      where party_id = p_party and user_id = auth.uid() and week = v_week and finished_at is not null;
      v_base := (array[12, 9, 7, 5, 4, 3, 3])[least(7, greatest(1, v_played))];
      v_growth := greatest(1, round(v_base * public.tier_rate(v_score))::int);
    end if;
    update public.member_progress
    set gold = gold + 500, attrs = jsonb_set(attrs, array[p_attr], to_jsonb(least(100, v_score + v_growth)))
    where party_id = p_party and user_id = auth.uid();
  else
    update public.member_progress set gold = greatest(0, gold - 150) where party_id = p_party and user_id = auth.uid();
  end if;
  v_result := jsonb_build_object('attr', p_attr, 'score', v_score, 'bonus', v_bonus, 'relic', v_relic, 'd20', v_d20, 'dc', v_dc,
                                 'net', v_net, 'pass', v_pass, 'growth', v_growth);
  update public.member_days set challenge = v_result, aside = false
  where party_id = p_party and user_id = auth.uid() and week = v_week and day = v_day;

  if v_d20 = 20 then
    perform public.post_natural_20(p_party, auth.uid(), 'challenge:' || v_week || ':' || v_day);
  end if;
  perform public.check_member_big_moments(p_party, auth.uid());

  return v_result;
end;
$$;

-- 5. fire_pieces: include laid fork road finds ('fork:<choice_id>:<branch_idx>')
create or replace function public.fire_pieces(p_party uuid, p_week int, p_day int) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare v_data jsonb := public.campfire_data(p_party, p_week, p_day); v_press jsonb; v_out jsonb := '[]'::jsonb;
begin
  -- Last-light finds: one piece per lead, with every finder.
  select coalesce(jsonb_agg(x.item order by x.first_at), '[]'::jsonb) into v_out from (
    select min(f.at) first_at, jsonb_build_object('key', 'lead:' || (l ->> 'id'), 'kind', 'lead',
      'title', l ->> 'clueTitle', 'text', l ->> 'clueText', 'source', l ->> 'place',
      'by', jsonb_agg(jsonb_build_object('id', f.user_id, 'name', m.character_name) order by f.at), 'at', min(f.at)) item
    from jsonb_array_elements(v_data -> 'leads') l
    join public.fan_outs f on f.party_id = p_party and f.week = p_week and f.day = p_day and f.lead_id = l ->> 'id'
    join public.party_members m on m.party_id = f.party_id and m.user_id = f.user_id
    group by l) x;
  -- Notice lines, each its friend's own.
  v_out := v_out || coalesce((select jsonb_agg(jsonb_build_object('key', 'notice:' || s.user_id, 'kind', 'notice',
      'title', 'What ' || m.character_name || ' noticed', 'attr', s.attr, 'text', s.body, 'source', s.attr,
      'by', jsonb_build_array(jsonb_build_object('id', s.user_id, 'name', m.character_name)), 'at', s.at) order by s.at)
    from public.fire_shares s join public.party_members m on m.party_id = s.party_id and m.user_id = s.user_id
    where s.party_id = p_party and s.week = p_week and s.day = p_day), '[]'::jsonb);
  -- The pass lines and the [PRESS ON] find: one piece each, with everyone who laid it.
  v_out := v_out || coalesce((select jsonb_agg(jsonb_build_object('key', 'pass', 'kind', 'pass',
      'title', 'What the passers heard', 'text', public.fire_pass_text(p_party, p_week, p_day), 'source', 'pass',
      'by', (select jsonb_agg(jsonb_build_object('id', l.user_id, 'name', m.character_name) order by l.at)
             from public.fire_laid l join public.party_members m on m.party_id = l.party_id and m.user_id = l.user_id
             where l.party_id = p_party and l.week = p_week and l.day = p_day and l.kind = 'pass'),
      'at', (select min(at) from public.fire_laid where party_id = p_party and week = p_week and day = p_day and kind = 'pass')))
    from (select 1) one
    where exists (select 1 from public.fire_laid where party_id = p_party and week = p_week and day = p_day and kind = 'pass')), '[]'::jsonb);
  v_press := public.fire_press_piece(p_party, p_week, p_day);
  v_out := v_out || coalesce((select jsonb_agg(jsonb_build_object('key', 'press', 'kind', 'press',
      'title', v_press ->> 'title', 'text', v_press ->> 'text', 'source', 'press',
      'by', (select jsonb_agg(jsonb_build_object('id', l.user_id, 'name', m.character_name) order by l.at)
             from public.fire_laid l join public.party_members m on m.party_id = l.party_id and m.user_id = l.user_id
             where l.party_id = p_party and l.week = p_week and l.day = p_day and l.kind = 'press'),
      'at', (select min(at) from public.fire_laid where party_id = p_party and week = p_week and day = p_day and kind = 'press')))
    from (select 1) one
    where v_press is not null
      and exists (select 1 from public.fire_laid where party_id = p_party and week = p_week and day = p_day and kind = 'press')), '[]'::jsonb);
  -- Fork road finds laid on the table: one piece per fork key, with everyone who laid it.
  v_out := v_out || coalesce((
    select jsonb_agg(fk.item order by fk.first_at)
    from (
      select
        l.kind as key,
        min(l.at) as first_at,
        jsonb_build_object(
          'key', l.kind,
          'kind', 'fork',
          'title', min(fp.title),
          'text', min(fp.body),
          'source', 'fork',
          'by', jsonb_agg(jsonb_build_object('id', l.user_id, 'name', m.character_name) order by l.at),
          'at', min(l.at)
        ) as item
      from public.fire_laid l
      join public.party_members m on m.party_id = l.party_id and m.user_id = l.user_id
      join public.fire_fork_pieces_for(p_party, p_week, p_day) fp on fp.key = l.kind and fp.user_id = l.user_id
      where l.party_id = p_party and l.week = p_week and l.day = p_day and l.kind like 'fork:%'
      group by l.kind
    ) fk
  ), '[]'::jsonb);
  return v_out;
end;
$$;

-- 6. fire_table: include unlaid fork road finds in v_hands and laid fork road finds in thread
create or replace function public.fire_table(p_party uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_week int; v_day int; v_me uuid := auth.uid(); v_data jsonb; v_narrated boolean; v_pieces jsonb;
        v_mine_pin public.fire_pins; v_passed boolean; v_pressed boolean; v_notice_passed boolean; v_notice jsonb; v_hands jsonb := '[]'::jsonb;
        v_press jsonb; v_prev_w int; v_prev_d int; v_readings jsonb; v_kinds int;
        v_fork record;
begin
  select o_week, o_day into v_week, v_day from public.my_fire_day(p_party);
  if not exists (select 1 from public.fan_outs where party_id = p_party and user_id = v_me and week = v_week and day = v_day) then
    raise exception 'not at the fire';
  end if;
  v_data := public.campfire_data(p_party, v_week, v_day);
  v_narrated := coalesce((v_data ->> 'narrated')::boolean, false);
  perform public.fire_check_clicks(p_party, v_week, v_day);
  v_pieces := public.fire_pieces(p_party, v_week, v_day);
  if v_narrated then
    select coalesce(jsonb_agg(p), '[]'::jsonb) into v_pieces from jsonb_array_elements(v_pieces) p
    where exists (select 1 from jsonb_array_elements(p -> 'by') b where b ->> 'id' = v_me::text);
  end if;
  select coalesce(jsonb_agg(p || jsonb_build_object(
      'mine', exists (select 1 from jsonb_array_elements(p -> 'by') b where b ->> 'id' = v_me::text),
      'agree', (select coalesce(jsonb_agg(m.character_name order by r.at), '[]'::jsonb) from public.fire_reactions r
                join public.party_members m on m.party_id = r.party_id and m.user_id = r.user_id
                where r.party_id = p_party and r.week = v_week and r.day = v_day and r.target = p ->> 'key' and r.kind = 'agree'),
      'doubt', (select coalesce(jsonb_agg(m.character_name order by r.at), '[]'::jsonb) from public.fire_reactions r
                join public.party_members m on m.party_id = r.party_id and m.user_id = r.user_id
                where r.party_id = p_party and r.week = v_week and r.day = v_day and r.target = p ->> 'key' and r.kind = 'doubt'),
      'myReaction', (select kind from public.fire_reactions where party_id = p_party and user_id = v_me and week = v_week and day = v_day
                     and target = p ->> 'key' and kind <> 'none')) order by p ->> 'at'), '[]'::jsonb)
    into v_pieces from jsonb_array_elements(v_pieces) p;

  if not v_narrated then
    select coalesce((notice ->> 'pass')::boolean, false),
           coalesce((challenge ->> 'pass')::boolean, false),
           coalesce((press ->> 'pass')::boolean, false)
      into v_notice_passed, v_passed, v_pressed
      from public.member_days
     where party_id = p_party and user_id = v_me and week = v_week and day = v_day;

    if coalesce(v_notice_passed, false) then
      v_notice := public.notice_line_for(p_party, v_me, v_week, v_day);
      if v_notice is not null and not exists (select 1 from public.fire_shares where party_id = p_party and user_id = v_me and week = v_week and day = v_day) then
        v_hands := v_hands || jsonb_build_object('kind', 'notice', 'title', 'What you noticed', 'attr', v_notice ->> 'attr', 'text', v_notice ->> 'text');
      end if;
    end if;

    if v_passed and public.fire_pass_text(p_party, v_week, v_day) is not null
       and not exists (select 1 from public.fire_laid where party_id = p_party and user_id = v_me and week = v_week and day = v_day and kind = 'pass') then
      v_hands := v_hands || jsonb_build_object('kind', 'pass', 'title', 'What you heard, because you passed', 'text', public.fire_pass_text(p_party, v_week, v_day));
    end if;
    v_press := public.fire_press_piece(p_party, v_week, v_day);
    if v_pressed and v_press is not null
       and not exists (select 1 from public.fire_laid where party_id = p_party and user_id = v_me and week = v_week and day = v_day and kind = 'press') then
      v_hands := v_hands || jsonb_build_object('kind', 'press', 'title', v_press ->> 'title', 'text', v_press ->> 'text');
    end if;

    -- Fork road finds held by this player that have not yet been laid on the table
    for v_fork in
      select fp.key, fp.title, fp.body
      from public.fire_fork_pieces_for(p_party, v_week, v_day) fp
      where fp.user_id = v_me
        and not exists (
          select 1 from public.fire_laid l
          where l.party_id = p_party and l.user_id = v_me and l.week = v_week and l.day = v_day and l.kind = fp.key
        )
    loop
      v_hands := v_hands || jsonb_build_object('kind', v_fork.key, 'title', v_fork.title, 'text', v_fork.body);
    end loop;
  end if;

  select * into v_mine_pin from public.fire_pins where party_id = p_party and user_id = v_me and week = v_week and day = v_day;
  if v_mine_pin.user_id is not null and not v_narrated then
    select coalesce(jsonb_agg(jsonb_build_object('id', fp.user_id, 'name', m.character_name, 'reading', fp.reading, 'line', fp.line,
        'mine', fp.user_id = v_me,
        'agree', (select coalesce(jsonb_agg(rm.character_name order by r.at), '[]'::jsonb) from public.fire_reactions r
                  join public.party_members rm on rm.party_id = r.party_id and rm.user_id = r.user_id
                  where r.party_id = p_party and r.week = v_week and r.day = v_day and r.target = 'pin:' || fp.user_id and r.kind = 'agree'),
        'doubt', (select coalesce(jsonb_agg(rm.character_name order by r.at), '[]'::jsonb) from public.fire_reactions r
                  join public.party_members rm on rm.party_id = r.party_id and rm.user_id = r.user_id
                  where r.party_id = p_party and r.week = v_week and r.day = v_day and r.target = 'pin:' || fp.user_id and r.kind = 'doubt'),
        'myReaction', (select kind from public.fire_reactions where party_id = p_party and user_id = v_me and week = v_week and day = v_day
                       and target = 'pin:' || fp.user_id and kind <> 'none')) order by fp.at), '[]'::jsonb)
      into v_readings
    from public.fire_pins fp join public.party_members m on m.party_id = fp.party_id and m.user_id = fp.user_id
    where fp.party_id = p_party and fp.week = v_week and fp.day = v_day;
  end if;
  select count(distinct reading) into v_kinds from public.fire_pins where party_id = p_party and week = v_week and day = v_day;

  if v_day > 1 then v_prev_w := v_week; v_prev_d := v_day - 1;
  elsif v_week > 1 then v_prev_w := v_week - 1; v_prev_d := 6;
  end if;

  return jsonb_build_object('week', v_week, 'day', v_day, 'narrated', v_narrated,
    'evening', (select extract(hour from now() at time zone time_zone) >= 20 from public.parties where id = p_party),
    'pieces', v_pieces,
    'hands', v_hands,
    'clicks', (select coalesce(jsonb_agg(jsonb_build_object('text', (v_data -> 'clicks' -> (k.idx - 1)) ->> 'text',
                 'names', to_jsonb(k.names), 'solves', coalesce(((v_data -> 'clicks' -> (k.idx - 1)) ->> 'solves')::boolean, false)) order by k.at), '[]'::jsonb)
               from public.fire_clicks k where k.party_id = p_party and k.week = v_week and k.day = v_day),
    'puzzle', v_data -> 'puzzle',
    'thread', case when v_narrated then '[]'::jsonb else (
      select coalesce(jsonb_agg(t.item order by t.at), '[]'::jsonb) from (
        select x.at, x.item from (
          select th.at, jsonb_build_object('kind', th.kind, 'name', m.character_name, 'mine', th.user_id = v_me, 'body', th.body, 'at', th.at) item
          from public.fire_thread th left join public.party_members m on m.party_id = th.party_id and m.user_id = th.user_id
          where th.party_id = p_party and th.week = v_week and th.day = v_day
          union all
          select f.at, jsonb_build_object('kind', 'laid', 'name', m.character_name, 'mine', f.user_id = v_me, 'body', l ->> 'clueTitle', 'at', f.at)
          from public.fan_outs f join public.party_members m on m.party_id = f.party_id and m.user_id = f.user_id
          join lateral jsonb_array_elements(v_data -> 'leads') l on l ->> 'id' = f.lead_id
          where f.party_id = p_party and f.week = v_week and f.day = v_day
          union all
          select s.at, jsonb_build_object('kind', 'laid', 'name', m.character_name, 'mine', s.user_id = v_me, 'body', 'What ' || m.character_name || ' noticed', 'at', s.at)
          from public.fire_shares s join public.party_members m on m.party_id = s.party_id and m.user_id = s.user_id
          where s.party_id = p_party and s.week = v_week and s.day = v_day
          union all
          select l.at, jsonb_build_object('kind', 'laid', 'name', m.character_name, 'mine', l.user_id = v_me,
                   'body', case
                     when l.kind = 'pass' then 'What the passers heard'
                     when l.kind = 'press' then coalesce(public.fire_press_piece(p_party, v_week, v_day) ->> 'title', 'A find')
                     else coalesce((select fp.title from public.fire_fork_pieces_for(p_party, v_week, v_day) fp where fp.key = l.kind limit 1), 'A find')
                   end, 'at', l.at)
          from public.fire_laid l join public.party_members m on m.party_id = l.party_id and m.user_id = l.user_id
          where l.party_id = p_party and l.week = v_week and l.day = v_day
        ) x order by x.at desc limit 200) t) end,
    'pinned', (select coalesce(jsonb_agg(m.character_name order by fp.at), '[]'::jsonb) from public.fire_pins fp
               join public.party_members m on m.party_id = fp.party_id and m.user_id = fp.user_id
               where fp.party_id = p_party and fp.week = v_week and fp.day = v_day and not v_narrated),
    'readings', v_readings,
    'leaning', case when v_narrated then null when v_kinds > 1 then 'split'
                    when v_kinds = 1 and v_mine_pin.user_id is not null
                         and (select count(*) from public.fire_pins where party_id = p_party and week = v_week and day = v_day) >= 2 then 'same' end,
    'lastCall', case when v_prev_w is not null then public.fire_call(p_party, v_prev_w, v_prev_d) end);
end;
$$;

-- 7. fire_lay: allow laying fork road finds ('fork:<choice_id>:<branch_idx>') onto the fire table
create or replace function public.fire_lay(p_party uuid, p_kind text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_week int; v_day int; v_ok boolean;
begin
  select o_week, o_day into v_week, v_day from public.my_fire_day(p_party);
  if not exists (select 1 from public.fan_outs where party_id = p_party and user_id = auth.uid() and week = v_week and day = v_day) then
    raise exception 'not at the fire';
  end if;
  if coalesce((public.campfire_data(p_party, v_week, v_day) ->> 'narrated')::boolean, false) then raise exception 'nothing to lay tonight'; end if;
  if p_kind = 'notice' then
    perform public.share_notice(p_party);
  elsif p_kind in ('pass', 'press') then
    select case p_kind when 'pass' then coalesce((challenge ->> 'pass')::boolean, false) and public.fire_pass_text(p_party, v_week, v_day) is not null
                       else coalesce((press ->> 'pass')::boolean, false) and public.fire_press_piece(p_party, v_week, v_day) is not null end
      into v_ok from public.member_days where party_id = p_party and user_id = auth.uid() and week = v_week and day = v_day;
    if not coalesce(v_ok, false) then raise exception 'nothing to lay'; end if;
    insert into public.fire_laid (party_id, user_id, week, day, kind) values (p_party, auth.uid(), v_week, v_day, p_kind)
    on conflict do nothing;
  elsif p_kind like 'fork:%' then
    if not exists (
      select 1 from public.fire_fork_pieces_for(p_party, v_week, v_day) fp
      where fp.user_id = auth.uid() and fp.key = p_kind
    ) then
      raise exception 'nothing to lay';
    end if;
    insert into public.fire_laid (party_id, user_id, week, day, kind) values (p_party, auth.uid(), v_week, v_day, p_kind)
    on conflict do nothing;
  else
    raise exception 'nothing to lay';
  end if;
  perform public.fire_check_clicks(p_party, v_week, v_day);
  return public.fire_table(p_party);
end;
$$;

revoke execute on function public.fire_fork_pieces_for(uuid, int, int), public.fire_pieces(uuid, int, int)
  from public, anon, authenticated;
revoke execute on function public.pick_choice(uuid, int, int), public.roll_card(uuid, text, boolean),
  public.fire_table(uuid), public.fire_lay(uuid, text) from public, anon;
grant execute on function public.pick_choice(uuid, int, int), public.roll_card(uuid, text, boolean),
  public.fire_table(uuid), public.fire_lay(uuid, text) to authenticated;
